        if visited[current]:
            return
        visited[current] = True
        for next in range(n):
            if distances[current][next] + costs[current] < costs[next]:
                costs[next] = distances[current][next] + costs[current]
                path[next] = current
        if not any(visited):
            return
        min_cost_city = sys.maxsize
        for city in range(n):
            if not visited[city]:
                min_cost_city = min(min_cost_city, costs[city])
        dfs(path[min_cost_city])

