from typing import List, Optional

def Combo(cost: int, lemonade: int, fries: int):
    def __init__(self, cost, lemonade, fries):
        self.cost = cost
        self.lemonade = lemonade
        self.fries = fries

    def __repr__(self) -> str:
        return f"Combo({self.cost}, {self.lemonade}, {self.fries})"

class Stock(object):
    def __init__(self, lemonade: int, fries: int):
        self.lemonade = lemonade
        self.fries = fries

def max_revenue(lemonade_stock: int, fries_stock: int, combo_a_cost: int, combo_a_lemonade: int, combo_a_fries: int, combo_b_cost: int, combo_b_lemonade: int, combo_b_fries: int) -> int:
    combo_a = Combo(combo_a_cost, combo_a_lemonade, combo_a_fries)
    combo_b = Combo(combo_b_cost, combo_b_lemonade, combo_b_fries)
    stock = Stock(lemonade_stock, fries_stock)

    def can_sell(combos: List[Combo], stock: Stock) -> Optional[int]:
        if sum([c.lemonade for c in combos] > stock.lemonade or sum([c.fries for c in combos]) > stock.fries:
            return None
        return sum([c.cost for c in combos])

    def sell_max(combos: List[Combo], stock: Stock) -> int:
        max_revenue = 0
        for i in range(stock.lemonade, -1, -1):
            for j in range(min(i, stock.fries), -1, -1):
                possible_combos = [combo_a if i >= combo_a.lemonade and j >= combo_a.fries else combo_b if i >= combo_b.lemonade and j >= combo_b.fries else None for combo in [combo_a, combo_b]]
                possible_combos = list(filter(None, possible_combos))
                revenue = can_sell(possible_combos, stock)
                if revenue is not None:
                    max_revenue = max(max_revenue, revenue)
        return max_revenue

    return sell_max([combo_a, combo_b], stock)
