from typing import Tuple, Optional

def Product(type_: int, raw_materials_kg: float, working_hours: float, profit: float):
    def __init__(self, type_, raw_materials_kg, working_hours, profit):
        self.type = type_
        self.raw_materials_kg = raw_materials_kg
        self.working_hours = working_hours
        self.profit = profit

    def __repr__(self) -> str:
        return f"Product({self.type}, {self.raw_materials_kg}, {self.working_hours}, {self.profit})"

class Factory:
    def __init__(self, raw_materials_kg: float, working_hours: float):
        self.raw_materials_kg = raw_materials_kg
        self.working_hours = working_hours
        self.products = {1: Product(1, 2.0, 30.0, 40000), 2: Product(2, 4.0, 15.0, 30000)}

    def can_produce(self, m: int, n: int) -> bool:
        total_raw_materials = (m * self.products[1].raw_materials_kg) + (n * self.products[2].raw_materials_kg)
        total_working_hours = (m * self.products[1].working_hours) + (n * self.products[2].working_hours)
        return total_raw_materials <= self.raw_materials_kg and total_working_hours <= self.working_hours

    def solve_production(self, m: int, n: int) -> Optional[float]:
        if not self.can_produce(m, n):
            return None
