def Menu(cost: int, milk_tea: int, cake: int):
    """A class representing a menu set."""

    def __init__(self, cost: int, milk_tea: int, cake: int):
        self.cost = cost
        self.milk_tea = milk_tea
        self.cake = cake

def max_charity_revenue(max_milk_tea: int, max_cakes: int, *menus: Tuple[Menu, ...]) -> Optional[int]:
    """Calculate the maximum total revenue that can be earned by selling given menu sets."""

    def dfs(remaining_milk_tea: int, remaining_cakes: int, current_revenue: int, current_menu: Menu):
        if not remaining_milk_tea or not remaining_cakes:
            return current_revenue

        revenue = current_revenue + current_menu.cost
        new_remaining_milk_tea = remaining_milk_tea - current_menu.milk_tea
        new_remaining_cakes = remaining_cakes - current_menu.cake

        if 0 <= new_remaining_milk_tea <= remaining_milk_tea and 0 <= new_remaining_cakes <= remaining_cakes:
            result = dfs(new_remaining_milk_tea, new_remaining_cakes, revenue, current_menu)
            if result is not None:
                return result

        for menu in menus:
            if menu != current_menu and 0 <= (new_remaining_milk_tea + menu.milk_tea) <= remaining_milk_tea and 0 <= (new_remaining_cakes + menu.cake) <= remaining_cakes:
                result = dfs(new_remaining_milk_tea + menu.milk_tea, new_remaining_cakes + menu.cake, revenue + menu.cost, menu)
                if result is not None:
                    return result

        return None

    return dfs(max_milk_tea, max_cakes, 0, None)
