    menu2 = create_menu(menu2_cost, milk_tea2, cake2 * 2)  # since Menu 2 includes 2 cakes

    def can_produce(menu: Tuple[int, int, int]) -> bool:
        return validate_limits(*menu)

    def produce_revenue(menus: List[Tuple[int, int, int]]) -> int:
        revenue = 0
        for menu in menus:
            revenue += menu[0] * (menu[1] + menu[2])
        return revenue

    def backtrack(remaining_milk_tea: int, remaining_cakes: int, menus: List[Tuple[int, int, int]], revenue: int):
        if not remaining_milk_tea or not remaining_cakes:
