                new_menus.append(menu)
                backtrack(remaining_milk_tea - menu[1], remaining_cakes - menu[2], new_menus, produce_revenue(new_menus))

    max_revenue = 0
    backtrack(milk_tea_limit, cake_limit, [menu1, menu2], 0)
    return max_revenue
