def calculate_p_scaled(n_shelves: int, n_books: int, scale_factor: int) -> int:
    if n_books > n_shelves or n_books % 2 == 1:
        return 0

    # Calculate the number of ways to place books such that no slot contains more than 2 books.
    total_combinations = combinations(range(n_books), n_books)
    valid_combinations = []

    for combination in total_combinations:
        if sum(combination) <= n_shelves and len(combination) > 1 and len(combination) < n_shelves + 1:
            valid_combinations.append(combination)

    # Calculate the number of combinations where exactly 4 slots or exactly 6 slots contain exactly 1 book.
    four_slots_one_book = len([comb for comb in valid_combinations if len(list(filter(lambda x: x == 1, comb))) == 4])
    six_slots_one_book = len([comb for comb in valid_combinations if len(list(filter(lambda x: x == 1, comb))) == 6])

    # Calculate the number of combinations where any slot containing 2 books must be surrounded by empty slots.
    two_books_surrounded = 0
    for combination in valid_combinations:
        if len([x for x in combination if x == 2]) > 0:
            left_empty, right_empty = True, True
            for i in range(len(combination) - 1):
                if combination[i] != 0 and combination[i + 1] != 0:
                    left_empty = False
                    break
            for i in range(1, len(combination)):
                if combination[i] != 0 and combination[i - 1] != 0:
                    right_empty = False
                    break
            if left_empty and right_empty:
                two_books_surrounded += 1

    # Calculate P and scale it by the given factor.
    p = (four_slots_one_book + six_slots_one_book) / len(valid_combinations) * two_books_surrounded / len(valid_combinations)
    return int(scale_factor * p)
